import { useId, type HTMLAttributes, type ReactNode, type Ref } from 'react';
import { cn } from '../../utils/cn';
import { sectionVariants, type SectionVariantProps } from './section.variants';

export interface SectionProps extends Omit<HTMLAttributes<HTMLElement>, 'className' | 'title'> {
  className?: string;
  ref?: Ref<HTMLElement>;
  /** `plain` (no surface), `card` (card surface + flat shadow) or `muted` (secondary well). */
  variant?: SectionVariantProps['variant'];
  /** Inner padding: none, sm, md or lg (lg grows on wider screens). */
  padding?: SectionVariantProps['padding'];
  /** Draws a rule under the header and between the children. */
  divided?: boolean;
  /** Header title; also names the section landmark (aria-labelledby). */
  title?: ReactNode;
  /** Supporting line under the title. */
  description?: ReactNode;
  /** Right-hand header slot (buttons, menu). */
  actions?: ReactNode;
  /** Heading level of the title that fits the page outline. */
  headingLevel?: 'h2' | 'h3' | 'h4';
  /** Class for the body wrapper around the children. */
  bodyClassName?: string;
}

/**
 * A painted content region (`<section>`): optional header (title, description, actions), padding and
 * dividers between its children.
 */
export function Section({
  variant,
  padding,
  divided,
  title,
  description,
  actions,
  headingLevel: Heading = 'h2',
  className,
  bodyClassName,
  children,
  ...props
}: SectionProps) {
  const id = useId();
  const titleId = `${id}-title`;
  const descId = `${id}-desc`;
  const s = sectionVariants({ variant, padding, divided });
  const hasHeader = title != null || description != null || actions != null;
  return (
    <section
      aria-labelledby={title != null ? titleId : undefined}
      aria-describedby={description != null ? descId : undefined}
      className={cn(s.root(), className)}
      {...props}
    >
      {hasHeader && (
        <div className={s.header()}>
          {title != null && <Heading id={titleId} className={s.title()}>{title}</Heading>}
          {description != null && <p id={descId} className={s.description()}>{description}</p>}
          {actions != null && <div className={s.actions()}>{actions}</div>}
        </div>
      )}
      <div className={cn(s.body(), bodyClassName)}>{children}</div>
    </section>
  );
}

export { Section, type SectionProps } from './Section';
export { sectionVariants, type SectionVariantProps } from './section.variants';
export { doc as sectionDoc } from './Section.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const sectionVariants = tv({
  slots: {
    root: 'min-w-0 text-foreground',
    header: 'grid grid-cols-[1fr_auto] items-start gap-x-4',
    title: 'col-start-1 text-[15px] font-semibold tracking-tight text-foreground',
    description: 'col-start-1 mt-0.5 text-[13px] leading-snug text-muted-foreground',
    actions: 'col-start-2 row-span-2 row-start-1 flex shrink-0 items-center gap-2 self-start',
    body: 'flex min-w-0 flex-col',
  },
  variants: {
    variant: {
      plain: {},
      card: { root: 'rounded-xl border border-border bg-card text-card-foreground shadow-sm' },
      muted: { root: 'rounded-xl border border-border bg-secondary/50' },
    },
    padding: {
      none: { root: 'p-0', header: 'mb-3', body: 'gap-4' },
      sm: { root: 'p-4', header: 'mb-3', body: 'gap-3' },
      md: { root: 'p-5', header: 'mb-4', body: 'gap-4' },
      lg: { root: 'p-6 sm:p-8', header: 'mb-5', body: 'gap-5' },
    },
    divided: {
      true: {
        header: 'border-b border-border',
        body: 'gap-0 divide-y divide-border *:py-4 *:first:pt-0 *:last:pb-0',
      },
    },
  },
  compoundVariants: [
    { divided: true, padding: 'none', class: { header: 'pb-3' } },
    { divided: true, padding: 'sm', class: { header: 'pb-3' } },
    { divided: true, padding: 'md', class: { header: 'pb-4' } },
    { divided: true, padding: 'lg', class: { header: 'pb-5' } },
  ],
  defaultVariants: { variant: 'plain', padding: 'none', divided: false },
});

export type SectionVariantProps = VariantProps<typeof sectionVariants>;

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'Section',
  group: 'Layout',
  status: 'stable',
  description:
    'A painted content region (<section>, named by its title). Variants plain / card / muted, padding none–lg, optional dividers between children, and a header slot with title, description and actions.',
  pattern: 'region',
  tokens: ['card', 'card-foreground', 'secondary', 'border', 'foreground', 'muted-foreground', 'shadow-sm', 'radius-xl'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
